arguments.argument:
sx = floor(view_xview / fgrid);
sy = floor(view_yview / fgrid);
ex = sx + dw;
ey = sy + dh;
surface_set_target(surf);
draw_clear(0);

if global.fog2_check=1
{
for (j = sy; j < ey; j += 1)
{
for (i = sx; i < ex; i += 1)
{
if falp[i, j]=2{draw_sprite_ext(spr_Fog, 0, i * fgrid - view_xview, j * fgrid - view_yview, fscale, fscale, 0, c_dkgray, 1)}
//반투명 포그를그림
if falp[i, j]=1 and global.fog_check=0 and global.fog2_check=1{draw_sprite_ext(spr_Fog, 0, i * fgrid - view_xview, j * fgrid - view_yview, fscale, fscale, 0, c_dkgray, 1)}

if falp[i, j]=0{draw_sprite_ext(spr_Fog, 0, i * fgrid - view_xview, j * fgrid - view_yview, fscale, fscale, 0, $ffffff, 0)}
//포그를 없앰
}
}
}

if global.fog_check=1
{
for (j = sy; j < ey; j += 1)
{
for (i = sx; i < ex; i += 1)
{
if falp[i, j]=1 and global.fog_check=1{draw_sprite_ext(spr_Fog, 0, i * fgrid - view_xview, j * fgrid - view_yview, fscale, fscale, 0, $ffffff, 1)}
//포그를 그림
}
}
}

surface_reset_target();
